INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-01', 'Dame un color', 'Fotografía algo de color amarillo que tengas cerca.', 'Busca un objeto amarillo y tómale una foto clara. Vale una fruta, una prenda, un cuaderno... lo importante es que el color se note.', 'observacion', 'facil', 'photo', 100, 40, 25, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-02', 'Arte con lo que hay', 'Arma una mini escena creativa con tres objetos.', 'Junta tres objetos a la mano y organízalos como una pequeña obra de arte. Gana la composición más original.', 'creatividad', 'medio', 'photo', 150, 60, 40, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-03', 'Mano amiga', 'Foto de tu mano sosteniendo el objeto más raro que encuentres.', 'Busca el objeto más inesperado de tu casa y muéstralo sostenido en tu mano.', 'ingenio', 'dificil', 'photo', 200, 80, 55, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-04', 'Sombra con cuento', 'Haz una sombra que parezca un animal.', 'Usa tus manos u objetos y una luz para proyectar la sombra de un animal. Que se entienda cuál es.', 'creatividad', 'medio', 'photo', 150, 60, 40, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-05', 'Tres redondos', 'Foto de tres objetos redondos juntos.', 'Encuentra tres cosas redondas distintas y fotografíalas en la misma imagen.', 'observacion', 'facil', 'photo', 100, 40, 25, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-06', 'El detalle escondido', 'Fotografía un detalle de tu entorno que casi nadie notaría.', 'Mira con calma a tu alrededor y captura algo pequeño que pasa desapercibido todos los días.', 'observacion', 'medio', 'photo', 150, 60, 40, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-07', 'Pose de campeón', 'Foto celebrando como si hubieras metido el gol de la final.', 'Pon tu mejor cara y tu mejor pose de celebración. Se vale gritar, pero la foto debe verse clara.', 'movimiento', 'facil', 'photo', 100, 40, 25, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-08', 'Equilibrio costeño', 'Foto con un objeto en equilibrio sobre tu cabeza.', 'Pon un objeto liviano sobre tu cabeza y tómate la foto sin que se caiga.', 'movimiento', 'dificil', 'photo', 200, 80, 55, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-09', 'Torre de ingenio', 'Apila cinco objetos distintos sin que se caigan.', 'Construye la torre más alta que puedas con cinco objetos diferentes y fotografíala de pie.', 'ingenio', 'medio', 'photo', 150, 60, 40, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
INSERT INTO retos (id, title, objective, description, category, difficulty, evidence_type, points, xp_reward, coin_reward, starts_at, ends_at, completed_by, total_members) VALUES ('cat-10', 'Cara de mango', 'Haz una cara con comida y fotografíala.', 'Usa frutas, arepas, galletas, lo que haya, para armar una carita con personalidad.', 'creatividad', 'facil', 'photo', 100, 40, 25, UTC_TIMESTAMP(), UTC_TIMESTAMP(), 0, 5);
